  font: 400 11px/1.4 var(--design-font-body);
  letter-spacing: .12em;
  color: var(--design-text-secondary);
}

.employee-login-page.auth-refinement-page .login-workspace {
  max-width: 40ch;
  overflow-wrap: anywhere;
  font: 400 12px/1.5 var(--design-font-body);
  color: var(--design-text-secondary);
  text-align: right;
}

.employee-login-page.auth-refinement-page .employee-login-composition {
  display: grid;
  grid-template-columns: minmax(0, .96fr) minmax(0, 1.04fr);
  overflow: clip;
  border: 1px solid var(--login-divider);
  border-radius: var(--login-frame-radius);
  background: var(--design-surface-elevated);
}

.employee-login-page.auth-refinement-page .login-visual {
  position: relative;
  isolation: isolate;
  display: block;
  padding: 0;
  min-width: 0;
  min-height: 608px;
  overflow: hidden;
  background: var(--login-hero-ink);
  color: var(--design-surface-elevated);
}

.employee-login-page.auth-refinement-page .login-visual-art {
  position: absolute;
  inset: 0;
  z-index: -2;
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 68%;
}

.employee-login-page.auth-refinement-page .login-visual::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(180deg, #062959B8 0%, #06295966 35%, transparent 66%);
}

.employee-login-page.auth-refinement-page .login-visual-copy { padding: 48px 44px; }

.employee-login-page.auth-refinement-page .login-visual h2 {
  max-width: 8.5ch;
  margin: 0;
  font: 500 clamp(44px, 4.4vw, 58px)/1.08 var(--design-font-body);
  letter-spacing: -.045em;
  text-wrap: balance;
}

html body .auth-refinement-page .employee-login-card {
  display: flex;
  flex-direction: column;
  justify-content: center;
  width: 100%;
  max-width: none;
  margin: 0;
  padding: 48px 56px;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  backdrop-filter: none;
  background: var(--design-surface-elevated);
}

.employee-login-page.auth-refinement-page .employee-login-heading { margin-bottom: 32px; }
.employee-login-page.auth-refinement-page .employee-login-heading h1 {
  margin: 0;
  font-size: 32px;
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: -.035em;
}

.employee-login-page.auth-refinement-page .employee-login-form { gap: 20px; }
.employee-login-page.auth-refinement-page .employee-login-form label { gap: 9px; font-size: 14px; font-weight: 500; }
.employee-login-page.auth-refinement-page .employee-login-form input {
  width: 100%;
  min-width: 0;
  height: 54px;
  padding: 12px 16px;
  border: 1px solid transparent;
  border-radius: var(--login-control-radius);
  font: 400 16px/1.5 var(--design-font-body);
  color: var(--design-text-primary);
  background: var(--login-field);
  transition: background .18s ease, border-color .18s ease;
}
.employee-login-page.auth-refinement-page .employee-login-form input::placeholder { color: #657083; }
html body .employee-login-page.auth-refinement-page .employee-login-form input:focus {
  border-color: var(--login-blue);
  background: var(--design-surface-elevated);
  box-shadow: 0 0 0 3px #0756D91A;
}

html body .employee-login-page.auth-refinement-page .employee-login-card .employee-login-submit.button.primary {
  display: flex;
  justify-content: center;
  min-height: 54px;
  margin-top: 4px;
  padding: 14px 18px;
  border-radius: var(--login-control-radius);
  font-size: 15px;
  font-weight: 600;
  background: var(--login-blue);
  border-color: var(--login-blue);
  color: var(--design-surface-elevated);
  transition: background .18s ease, border-color .18s ease, transform .18s ease;
}
html body .employee-login-page.auth-refinement-page .employee-login-card .employee-login-submit.button.primary:is(:hover, :active):not(:disabled) {
  background: var(--login-blue-hover);
  border-color: var(--login-blue-hover);
  color: var(--design-surface-elevated);
}
.employee-login-page.auth-refinement-page .employee-login-submit:active:not(:disabled) { transform: scale(.99); }
.employee-login-page.auth-refinement-page .employee-login-submit:disabled { opacity: 1; cursor: wait; }
.employee-login-page.auth-refinement-page .login-submit-status {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.employee-login-page.auth-refinement-page .employee-login-secondary {
  display: grid;
  gap: 8px;
  justify-content: stretch;
  align-items: stretch;
  margin-top: 28px;
  padding: 20px 0 0;
  border-color: var(--login-divider);
}

.employee-login-page.auth-refinement-page .login-access-link {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr);
  align-items: center;
  gap: 14px;
  min-height: 56px;
  padding: 4px 0;
  border-radius: 8px;
  color: var(--login-blue);
  font-size: 14px;
  font-weight: 500;
  text-decoration: none;
  text-underline-offset: 4px;
}
.employee-login-page.auth-refinement-page .login-access-link > span:last-child { display: grid; gap: 4px; }
.employee-login-page.auth-refinement-page .login-access-symbol {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: var(--login-symbol-radius);
  background: var(--login-ice);
  color: var(--login-blue);
  transition: background .18s ease;
}
.employee-login-page.auth-refinement-page .login-access-link small { color: var(--design-text-secondary); font-size: 12px; font-weight: 400; }
.employee-login-page.auth-refinement-page .login-access-link:hover > span:last-child { text-decoration: underline; }
html body .employee-login-page.auth-refinement-page .login-access-link:is(:hover, :active) { color: var(--login-blue-hover); }
.employee-login-page.auth-refinement-page .login-access-link:hover .login-access-symbol { background: #E3F3FC; }
.employee-login-page.auth-refinement-page :is(input, button, a):focus-visible { outline: 2px solid var(--login-blue); outline-offset: 4px; }
.employee-login-page.auth-refinement-page :is(.form-error, .form-success) { margin: 0 0 20px; font-size: 14px; line-height: 1.5; }

html body .auth-refinement-page .employee-login-footer { gap: 8px; }
html body .auth-refinement-page .employee-login-footer small { font-size: 10px; font-weight: 500; letter-spacing: .1em; }
.employee-login-page.auth-refinement-page .brand-legal { display: flex; flex-wrap: wrap; justify-content: center; gap: 4px 16px; }
html body .employee-login-page.auth-refinement-page .brand-legal span { font-size: 11px; line-height: 1.5; }

@media (min-width: 800px) and (max-width: 1050px) {
  html body .auth-refinement-page .employee-login-card { padding: 40px 32px; }
  .employee-login-page.auth-refinement-page .login-visual-copy { padding: 44px 32px; }
  .employee-login-page.auth-refinement-page .login-visual h2 { font-size: 44px; }
}

@media (min-width: 800px) and (max-height: 800px) {
  html body .employee-login-page.auth-refinement-page { padding-block: 16px; }
  html body .auth-refinement-page .employee-login-shell { gap: 20px; }
  html body .auth-refinement-page .employee-login-card { padding-block: 36px; }
  .employee-login-page.auth-refinement-page .login-visual { min-height: 560px; }
  .employee-login-page.auth-refinement-page .employee-login-heading { margin-bottom: 28px; }
  .employee-login-page.auth-refinement-page .employee-login-secondary { margin-top: 24px; padding-top: 16px; gap: 4px; }
}

@media (max-width: 799px) {
  html body .employee-login-page.auth-refinement-page { padding: max(24px, env(safe-area-inset-top)) 20px max(20px, env(safe-area-inset-bottom)); }
  html body .auth-refinement-page .employee-login-shell { width: min(480px, 100%); gap: 24px; }
  html body .auth-refinement-page .employee-login-brand { align-items: center; flex-wrap: wrap; gap: 16px; }
  .employee-login-page.auth-refinement-page .login-brand-lockup .brand-wordmark { width: 160px; }
  .employee-login-page.auth-refinement-page .login-brand-module { font-size: 10px; }
  .employee-login-page.auth-refinement-page .login-workspace { max-width: 46%; font-size: 11px; }
  .employee-login-page.auth-refinement-page .employee-login-composition { grid-template-columns: minmax(0, 1fr); border-radius: 20px; }
  .employee-login-page.auth-refinement-page .login-visual { min-height: 144px; }
  .employee-login-page.auth-refinement-page .login-visual-art { object-position: 50% 42%; }
  .employee-login-page.auth-refinement-page .login-visual::after { background: linear-gradient(90deg, #062959DB, #06295980 60%, #06295914); }
  .employee-login-page.auth-refinement-page .login-visual-copy { padding: 28px; }
  .employee-login-page.auth-refinement-page .login-visual h2 { max-width: 10ch; font-size: 30px; line-height: 1.14; letter-spacing: -.035em; }
  html body .auth-refinement-page .employee-login-card { padding: 32px 28px 28px; }
  .employee-login-page.auth-refinement-page .employee-login-heading { margin-bottom: 28px; }
  .employee-login-page.auth-refinement-page .employee-login-heading h1 { font-size: 28px; }
  .employee-login-page.auth-refinement-page .employee-login-form { gap: 18px; }
  .employee-login-page.auth-refinement-page .employee-login-secondary { margin-top: 24px; padding-top: 16px; }
  .employee-login-page.auth-refinement-page .brand-legal { display: grid; gap: 4px; }
}

@media (max-width: 360px) {
  html body .employee-login-page.auth-refinement-page { padding-inline: 16px; }
  .employee-login-page.auth-refinement-page .login-brand-lockup .brand-wordmark { width: 144px; }
  .employee-login-page.auth-refinement-page .login-workspace { max-width: 44%; }
  html body .auth-refinement-page .employee-login-card { padding-inline: 22px; }
  .employee-login-page.auth-refinement-page .login-visual-copy { padding-inline: 22px; }
  .employee-login-page.auth-refinement-page .employee-login-heading h1 { font-size: 26px; }
}

@media (prefers-reduced-motion: reduce) {
  .employee-login-page.auth-refinement-page :is(.employee-login-submit, .employee-login-form input, .login-access-symbol) { transition: none; }
  .employee-login-page.auth-refinement-page .employee-login-submit:active:not(:disabled) { transform: none; }
}

/* Recovery, activation and reset extend the approved login geometry with neutral still artwork. */
.employee-login-page.auth-support-page {
  --auth-still-surface: #F1F4F8;
  --auth-popover-radius: 14px;
}

.employee-login-page.auth-support-page .login-visual {
  display: flex;
  flex-direction: column;
  background: var(--auth-still-surface);
  color: var(--design-text-primary);
}
.employee-login-page.auth-support-page .login-visual::after { display: none; }
.employee-login-page.auth-support-page .login-visual-copy { flex: none; }
.employee-login-page.auth-support-page .auth-still-stage {
  display: grid;
  place-items: center;
  flex: 1;
  min-width: 0;
  padding: 0 24px 64px;
}
.employee-login-page.auth-support-page .login-visual-art {
  position: static;
  z-index: auto;
  width: 100%;
  height: auto;
  object-fit: contain;
  transform: none;
}

.employee-login-page.auth-support-page .employee-login-card { justify-content: center; }
.employee-login-page.auth-support-page :is(.recovery-secondary, .activation-secondary, .reset-secondary) {
  margin-top: 28px;
  padding-top: 16px;
  border-color: var(--login-divider);
}
.employee-login-page.auth-support-page :is(.recovery-help, .activation-help, .reset-help) { border: 0; }
.employee-login-page.auth-support-page :is(.recovery-help, .activation-help, .reset-help) summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 56px;
  padding: 8px 0;
  border-radius: 8px;
  list-style: none;
  color: var(--design-text-secondary);
  font-size: 14px;
  font-weight: 400;
  cursor: pointer;
}
.employee-login-page.auth-support-page summary::-webkit-details-marker { display: none; }
.employee-login-page.auth-support-page .auth-disclosure-symbol {
  display: grid;
  place-items: center;
  flex: none;
  width: 26px;
  height: 26px;
  border: 1px solid var(--login-divider);
  border-radius: 50%;
  color: var(--design-text-secondary);
  background: var(--design-surface-elevated);
}
.employee-login-page.auth-support-page .auth-disclosure-symbol svg { grid-area: 1 / 1; transform: none; transition: none; }
.employee-login-page.auth-support-page .auth-disclosure-open { display: none; }
.employee-login-page.auth-support-page details[open] > summary .auth-disclosure-open { display: block; }
.employee-login-page.auth-support-page details[open] > summary .auth-disclosure-closed { display: none; }
.employee-login-page.auth-support-page :is(.recovery-help, .activation-help, .reset-help) summary:hover { color: var(--login-blue); }
.employee-login-page.auth-support-page :is(.recovery-help, .activation-help, .reset-help) p {
  margin: 4px 0 16px;
  font-size: 13px;
  line-height: 1.6;
  color: var(--design-text-secondary);
}
.employee-login-page.auth-support-page :is(.recovery-back, .activation-back, .reset-back) {
  display: flex;
  align-items: center;
  min-height: 44px;
  margin-top: 12px;
  width: fit-content;
  padding: 4px 0;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 500;
}

.employee-login-page.auth-support-page .recovery-email-field { display: grid; gap: 9px; min-width: 0; }
.employee-login-page.auth-support-page .auth-label-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.employee-login-page.auth-support-page .auth-field-help { position: relative; flex: none; width: 44px; }
.employee-login-page.auth-support-page .auth-field-help summary {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  margin-block: -11px;
  padding: 0;
  border-radius: 50%;
  color: var(--design-text-secondary);
  list-style: none;
  cursor: pointer;
}
.employee-login-page.auth-support-page .auth-field-help summary:hover { color: var(--login-blue); background: var(--login-field); }
.employee-login-page.auth-support-page .auth-field-help p {
  position: absolute;
  z-index: 3;
  top: calc(100% + 14px);
  right: 0;
  width: min(280px, calc(100vw - 104px));
  margin: 0;
  padding: 16px 18px;
  border: 1px solid var(--login-divider);
  border-radius: var(--auth-popover-radius);
  background: var(--design-surface-elevated);
  color: var(--design-text-secondary);
  box-shadow: 0 6px 24px #11182710;
  font-size: 13px;
  line-height: 1.6;
}
.employee-login-page.auth-support-page :is(summary, .recovery-receipt, .recovery-error, .reset-receipt, .reset-error):focus-visible {
  outline: 2px solid var(--login-blue);
  outline-offset: 4px;
}
.employee-login-page.auth-support-page :is(.recovery-receipt, .reset-receipt, .reset-error) { border-radius: var(--login-control-radius); }
.employee-login-page.auth-support-page :is(.activation-password-toggle, .reset-password-toggle) { top: 5px; border-radius: 9px; }

@media (max-width: 799px) {
  .employee-login-page.auth-support-page .login-visual {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 40%;
    align-items: center;
    min-height: 144px;
  }
  .employee-login-page.auth-support-page .login-visual-copy { padding: 24px 0 24px 28px; }
  .employee-login-page.auth-support-page .login-visual h2 { max-width: 8.5ch; font-size: 28px; }
  .employee-login-page.auth-support-page .auth-still-stage { padding: 0 8px 0 0; }
  .employee-login-page.auth-support-page :is(.recovery-secondary, .activation-secondary, .reset-secondary) { margin-top: 24px; padding-top: 16px; }
}
@media (max-width: 360px) {
  .employee-login-page.auth-support-page .login-visual-copy { padding-left: 22px; }
  .employee-login-page.auth-support-page .login-visual h2 { font-size: 24px; }
  .employee-login-page.auth-support-page :is(.recovery-help, .activation-help, .reset-help) summary { font-size: 13px; }
}
